import React, { useState, useRef } from 'react';
import { Container, Row, Col, Card, Form, Button, Alert, ProgressBar, Nav, Tab, Spinner } from 'react-bootstrap';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import FilePreview from '../components/FilePreview';
import FieldMapping from '../components/FieldMapping';
import { usePortfolio } from '../context/PortfolioContext';

const ImportPortfolio = () => {
  const navigate = useNavigate();
  const { processTransactionsFile, processSummaryFile, loading, error } = usePortfolio();
  const [file, setFile] = useState(null);
  const [fileType, setFileType] = useState('transactions');
  const [uploading, setUploading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [message, setMessage] = useState({ text: '', type: '' });
  const [previewData, setPreviewData] = useState([]);
  const [headers, setHeaders] = useState([]);
  const [mappedFields, setMappedFields] = useState({
    transactions: {
      date: '',
      symbol: '',
      action: '',
      quantity: '',
      price: '',
      brokerage: '',
      companyName: ''
    },
    summary: {
      symbol: '',
      companyName: '',
      quantity: '',
      avgCostPrice: '',
      currentPrice: '',
      valueAtCost: '',
      valueAtMarket: '',
      unrealizedPL: '',
      unrealizedPLPercent: ''
    }
  });

  const fileInputRef = useRef(null);

  const handleFileChange = (e) => {
    const selectedFile = e.target.files[0];
    if (selectedFile) {
      setFile(selectedFile);
      readFilePreview(selectedFile);
    }
  };

  const readFilePreview = (file) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const content = e.target.result;
      const lines = content.split('\n');

      if (lines.length > 0) {
        const headerLine = lines[0];
        const headerFields = headerLine.split(',').map(h => h.trim());
        setHeaders(headerFields);

        // Get up to 5 rows for preview
        const previewRows = [];
        for (let i = 1; i < Math.min(lines.length, 6); i++) {
          const line = lines[i].trim();
          if (line) {
            const values = line.split(',').map(v => v.trim());
            previewRows.push(values);
          }
        }
        setPreviewData(previewRows);
      }
    };
    reader.readAsText(file);
  };

  const handleFieldMapping = (fileType, field, headerName) => {
    setMappedFields(prev => ({
      ...prev,
      [fileType]: {
        ...prev[fileType],
        [field]: headerName
      }
    }));
  };

  const handleFileTypeChange = (type) => {
    setFileType(type);
  };

  const handleUpload = async () => {
    if (!file) {
      alert('Please select a file to upload');
      return;
    }

    // Check if required fields are mapped
    const currentMapping = mappedFields[fileType];
    const requiredFields = fileType === 'transactions' 
      ? ['date', 'symbol', 'action', 'quantity', 'price']
      : ['symbol', 'quantity', 'avgCostPrice', 'currentPrice'];

    const missingFields = requiredFields.filter(field => !currentMapping[field]);

    if (missingFields.length > 0) {
      alert(`Please map the following required fields: ${missingFields.join(', ')}`);
      return;
    }

    try {
      let result;

      if (fileType === 'transactions') {
        result = await processTransactionsFile(file, headers, currentMapping);
      } else if (fileType === 'summary') {
        result = await processSummaryFile(file, headers, currentMapping);
      }

      if (result) {
        navigate('/portfolio');
      }
    } catch (error) {
      console.error('Error uploading file:', error);
    }
  };

  const downloadSampleCSV = () => {
    let csvContent = '';

    if (fileType === 'transactions') {
      csvContent = 'Date,Symbol,Action,Quantity,Price,Brokerage,Company Name\n' +
        '2023-01-15,AAPL,BUY,10,175.25,5.99,Apple Inc.\n' +
        '2023-02-20,MSFT,BUY,5,280.50,5.99,Microsoft Corporation\n' +
        '2023-03-10,AAPL,SELL,3,180.75,5.99,Apple Inc.\n' +
        '2023-04-05,GOOGL,BUY,2,2750.00,7.99,Alphabet Inc.\n' +
        '2023-05-12,AMZN,BUY,8,135.75,5.99,Amazon.com Inc.';
    } else {
      csvContent = 'Symbol,Company Name,Quantity,Avg Cost Price,Current Price,Value at Cost,Value at Market,Unrealized P/L,Unrealized P/L %\n' +
        'AAPL,Apple Inc.,25,150.25,180.50,3756.25,4512.50,756.25,20.13\n' +
        'MSFT,Microsoft Corporation,15,250.75,300.25,3761.25,4503.75,742.50,19.74\n' +
        'GOOGL,Alphabet Inc.,5,2500.00,2800.00,12500.00,14000.00,1500.00,12.00\n' +
        'AMZN,Amazon.com Inc.,20,120.50,150.25,2410.00,3005.00,595.00,24.69';
    }

    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = fileType === 'transactions' ? 'sample_transactions.csv' : 'sample_portfolio_summary.csv';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const renderFieldMappingForm = () => {
    const currentMapping = mappedFields[fileType];
    const fields = Object.keys(currentMapping);

    return (
      <Card className="mb-4">
        <Card.Header>Map File Columns</Card.Header>
        <Card.Body>
          <p className="text-muted mb-3">
            Match your file columns to the required fields. Required fields are marked with *.
          </p>

          <Row>
            {fields.map(field => (
              <Col md={6} key={field} className="mb-3">
                <Form.Group>
                  <Form.Label>
                    {field.charAt(0).toUpperCase() + field.slice(1).replace(/([A-Z])/g, ' $1')}
                    {(fileType === 'transactions' && ['date', 'symbol', 'action', 'quantity', 'price'].includes(field)) ||
                     (fileType === 'summary' && ['symbol', 'quantity', 'avgCostPrice', 'currentPrice'].includes(field)) 
                      ? ' *' : ''}
                  </Form.Label>
                  <Form.Select 
                    value={currentMapping[field]} 
                    onChange={(e) => handleFieldMapping(fileType, field, e.target.value)}
                  >
                    <option value="">-- Select Column --</option>
                    {headers.map((header, index) => (
                      <option key={index} value={header}>{header}</option>
                    ))}
                  </Form.Select>
                </Form.Group>
              </Col>
            ))}
          </Row>
        </Card.Body>
      </Card>
    );
  };

  return (
    <Container className="mt-4">
      <h1 className="mb-4">Import Portfolio Data</h1>

      {message.text && (
        <Alert variant={message.type}>
          {message.text}
          {message.type === 'success' && (
            <div className="mt-2">
              <Button variant="primary" onClick={() => navigate('/portfolios')}>
                View Portfolio
              </Button>
            </div>
          )}
        </Alert>
      )}

      <Row>
        <Col lg={6} className="mb-4">
          <Card>
            <Card.Body>
              <Card.Title>Upload Portfolio File</Card.Title>
              <Card.Text>
                Import your portfolio data from a CSV file.
              </Card.Text>

              <Form onSubmit={handleUpload}>
                <Form.Group className="mb-3">
                  <Form.Label>Choose File</Form.Label>
                  <div className="d-flex">
                    <Form.Control 
                      type="file" 
                      accept=".csv" 
                      onChange={handleFileChange}
                      ref={fileInputRef}
                      disabled={uploading}
                    />
                    <Button 
                      variant="outline-secondary" 
                      onClick={downloadSampleCSV}
                      className="ms-2"
                      disabled={uploading}
                    >
                      Download Sample
                    </Button>
                  </div>

                  {file && (
                    <div className="mt-2 mb-3">
                      <p><strong>Selected file:</strong> {file.name}</p>
                    </div>
                  )}

                  <FilePreview previewData={previewData} headers={headers} />

                  {uploading && (
                    <ProgressBar 
                      now={progress} 
                      label={`${progress}%`} 
                      className="mb-3"
                      animated
                    />
                  )}
                </Form.Group>

                <Button 
                  variant="primary" 
                  type="submit" 
                  disabled={!file || uploading}
                >
                  {uploading ? (
                    <>
                      <Spinner as="span" animation="border" size="sm" role="status" aria-hidden="true" className="me-2" />
                      Processing...
                    </>
                  ) : 'Upload Portfolio'}
                </Button>
              </Form>
            </Card.Body>
          </Card>
        </Col>

        <Col lg={6}>
          <Card>
            <Card.Body>
              <Card.Title>Column Mapping</Card.Title>
              <Card.Text>
                Map the columns in your file to the required fields.
              </Card.Text>

              {renderFieldMappingForm()}
            </Card.Body>
          </Card>
        </Col>
      </Row>

      <Row className="mt-4">
        <Col>
          <Card>
            <Card.Body>
              <Card.Title>File Format Guidelines</Card.Title>

              <Tab.Container defaultActiveKey={fileType}>
                <Nav variant="tabs" className="mb-3">
                  <Nav.Item>
                    <Nav.Link eventKey="transactions">Transactions File</Nav.Link>
                  </Nav.Item>
                  <Nav.Item>
                    <Nav.Link eventKey="summary">Summary File</Nav.Link>
                  </Nav.Item>
                </Nav>

                <Tab.Content>
                  <Tab.Pane eventKey="transactions">
                    <div className="mt-3">
                      <h5>Transaction File Format</h5>
                      <p>Your transaction file should contain the following information:</p>

                      <ul>
                        <li><strong>Stock Symbol:</strong> The ticker symbol of the security</li>
                        <li><strong>Company Name:</strong> The full name of the company</li>
                        <li><strong>ISIN Code:</strong> International Securities Identification Number</li>
                        <li><strong>Action:</strong> Buy or Sell</li>
                        <li><strong>Quantity:</strong> Number of shares</li>
                        <li><strong>Transaction Price:</strong> Price per share</li>
                        <li><strong>Transaction Date:</strong> Date of transaction (DD-MMM-YYYY format preferred)</li>
                        <li><strong>Brokerage/Fees:</strong> Any transaction fees or commissions</li>
                        <li><strong>Exchange:</strong> Stock exchange (e.g., NSE, BSE)</li>
                      </ul>

                      <h6 className="mt-3 mb-0">Example transaction CSV format:</h6>
                      <pre className="bg-light p-2 mt-2">
                        Stock Symbol,Company Name,ISIN Code,Action,Quantity,Transaction Price,Brokerage,Transaction Charges,StampDuty,Segment,STT Paid/Not Paid,Remarks,Transaction Date,Exchange<br/>
                        AARIND,AARTI INDUSTRIES LTD,INE769A01020,Buy,10,448.00,13.24,0.14,0.00,TT,STT Paid,icicidirect,21-Aug-2023,NSE<br/>
                        AARIND,AARTI INDUSTRIES LTD,INE769A01020,Sell,5,460.00,6.82,0.07,0.00,TT,STT Paid,icicidirect,15-Sep-2023,NSE
                      </pre>

                      <div className="mt-3">
                        <Button variant="outline-primary" href="/sample_transactions.csv" download>
                          Download Sample Transactions CSV
                        </Button>
                      </div>
                    </div>
                  </Tab.Pane>

                  <Tab.Pane eventKey="summary">
                    <div className="mt-3">
                      <h5>Summary File Format</h5>
                      <p>Your portfolio summary file should contain the following information:</p>

                      <ul>
                        <li><strong>Stock Symbol:</strong> The ticker symbol of the security</li>
                        <li><strong>Company Name:</strong> The full name of the company</li>
                        <li><strong>ISIN Code:</strong> International Securities Identification Number</li>
                        <li><strong>Qty:</strong> Number of shares held</li>
                        <li><strong>Average Cost Price:</strong> Average cost of acquisition per share</li>
                        <li><strong>Current Market Price:</strong> Current market price per share</li>
                        <li><strong>Value At Cost:</strong> Total cost of acquisition</li>
                        <li><strong>Value At Market Price:</strong> Current market value of holding</li>
                        <li><strong>Realized Profit/Loss:</strong> Profit/loss from sold positions</li>
                        <li><strong>Unrealized Profit/Loss:</strong> Unrealized profit/loss on current positions</li>
                      </ul>

                      <h6 className="mt-3 mb-0">Example summary CSV format:</h6>
                      <pre className="bg-light p-2 mt-2">
                        Stock Symbol,Company Name,ISIN Code,Qty,Average Cost Price,Current Market Price,% Change over prev close,Value At Cost,Value At Market Price,Realized Profit / Loss,Unrealized Profit/Loss,Unrealized Profit/Loss %<br/>
                        AARIND,AARTI INDUSTRIES LTD,INE769A01020,2995,455.18,376.00,- 5.01,1363264.10,1126120.00,0.00,-237144.10,(17.40)<br/>
                        ADAPOR,ADANI PORT AND SPECIAL ECONO,INE742F01042,0,0.00,1069.40,- 0.89,0.00,0.00,11123.10,0.00,0.00
                      </pre>

                      <div className="mt-3">
                        <Button variant="outline-primary" href="/sample_summary.csv" download>
                          Download Sample Summary CSV
                        </Button>
                      </div>
                    </div>
                  </Tab.Pane>
                </Tab.Content>
              </Tab.Container>
            </Card.Body>
          </Card>
        </Col>
      </Row>
    </Container>
  );
};

export default ImportPortfolio;
